import javax.swing.*;import java.awt.*;import java.sql.*;
public class CustomerFrame extends JFrame{JTextField n=new JTextField(),ph=new JTextField(),em=new JTextField();JTextArea ad=new JTextArea();public CustomerFrame(){setTitle("Manage Customers");setSize(600,520);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(null);p.setBackground(new Color(230,240,255));JLabel h=new JLabel("MANAGE CUSTOMERS",SwingConstants.CENTER);h.setFont(new Font("Arial",1,22));h.setBounds(150,25,300,35);p.add(h);lab(p,"Customer Name:",60,90);fld(p,n,200,90);lab(p,"Phone:",60,140);fld(p,ph,200,140);lab(p,"Email:",60,190);fld(p,em,200,190);lab(p,"Address:",60,240);JScrollPane s=new JScrollPane(ad);s.setBounds(200,240,300,80);p.add(s);JButton b=new JButton("ADD CUSTOMER");b.setBounds(100,370,170,40);p.add(b);JButton c=new JButton("CLEAR");c.setBounds(320,370,150,40);p.add(c);b.addActionListener(e->add());c.addActionListener(e->{n.setText("");ph.setText("");em.setText("");ad.setText("");});add(p);}void lab(JPanel p,String s,int x,int y){JLabel l=new JLabel(s);l.setBounds(x,y,130,30);p.add(l);}void fld(JPanel p,JTextField f,int x,int y){f.setBounds(x,y,300,30);p.add(f);}void add(){if(n.getText().trim().isEmpty()){JOptionPane.showMessageDialog(this,"Customer name required!");return;}try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement("INSERT INTO BANK_CUSTOMERS VALUES(BANK_CUSTOMER_SEQ.NEXTVAL,?,?,?,?)")){q.setString(1,n.getText().trim());q.setString(2,ph.getText().trim());q.setString(3,em.getText().trim());q.setString(4,ad.getText().trim());q.executeUpdate();JOptionPane.showMessageDialog(this,"Customer Added Successfully!");}catch(SQLException e){JOptionPane.showMessageDialog(this,"Database Error: "+e.getMessage());}}}
